PRAGMA foreign_keys=ON;
CREATE TABLE tblCarType (CarTypeID INTEGER PRIMARY KEY AUTOINCREMENT, TypeName TEXT NOT NULL UNIQUE, Manufacturer TEXT, PMIntervalKm INTEGER NOT NULL, PMIntervalDays INTEGER NOT NULL);
CREATE TABLE tblCarStatus (CarStatusID INTEGER PRIMARY KEY AUTOINCREMENT, StatusName TEXT NOT NULL UNIQUE);
CREATE TABLE tblLocation (LocationID INTEGER PRIMARY KEY AUTOINCREMENT, LocationName TEXT NOT NULL UNIQUE, LocationType TEXT NOT NULL);
CREATE TABLE tblCar (CarID INTEGER PRIMARY KEY AUTOINCREMENT, CarNumber TEXT NOT NULL UNIQUE, CarTypeID INTEGER NOT NULL, CarStatusID INTEGER NOT NULL, LocationID INTEGER, InServiceDate TEXT NOT NULL, CurrentOdometerKm INTEGER NOT NULL);
CREATE TABLE tblTechnician (TechID INTEGER PRIMARY KEY AUTOINCREMENT, EmployeeNo TEXT NOT NULL UNIQUE, FullName TEXT NOT NULL, Trade TEXT, IsActive INTEGER NOT NULL);
CREATE TABLE tblPriority (PriorityID INTEGER PRIMARY KEY AUTOINCREMENT, PriorityName TEXT NOT NULL UNIQUE, TargetHours INTEGER NOT NULL);
CREATE TABLE tblWOType (WOTypeID INTEGER PRIMARY KEY AUTOINCREMENT, WOTypeName TEXT NOT NULL UNIQUE);
CREATE TABLE tblWOStatus (WOStatusID INTEGER PRIMARY KEY AUTOINCREMENT, WOStatusName TEXT NOT NULL UNIQUE);
CREATE TABLE tblWorkOrder (WOID INTEGER PRIMARY KEY AUTOINCREMENT, CarID INTEGER NOT NULL, WOTypeID INTEGER NOT NULL, PriorityID INTEGER NOT NULL, WOStatusID INTEGER NOT NULL, AssignedTechID INTEGER, OpenedDate TEXT NOT NULL, DueDate TEXT, ClosedDate TEXT, OdometerKm INTEGER, DefectDescription TEXT NOT NULL, ClosureNotes TEXT);
CREATE TABLE tblLabour (LabourID INTEGER PRIMARY KEY AUTOINCREMENT, WOID INTEGER NOT NULL, TechID INTEGER NOT NULL, WorkDate TEXT NOT NULL, Hours REAL NOT NULL);
CREATE TABLE tblPart (PartID INTEGER PRIMARY KEY AUTOINCREMENT, PartNumber TEXT NOT NULL UNIQUE, PartName TEXT NOT NULL, UnitCost REAL NOT NULL);
CREATE TABLE tblPartUsed (PartUsedID INTEGER PRIMARY KEY AUTOINCREMENT, WOID INTEGER NOT NULL, PartID INTEGER NOT NULL, Quantity INTEGER NOT NULL);